def list_workspaces(status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0308000" if __import__("os").path.isdir("./environment_mix/0308000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, status_code, meta=None, started=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = None
        if isinstance(started, (int, float)):
            latency_ms = int((time.time() - started) * 1000)
        row = {
            "id": f"lin_req_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}",
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": latency_ms,
            "credential_id": None,
            "workspace_id": None,
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    started = time.time()

    # Validate inputs (per schema) but relax cursor format: accept an id cursor (as observed) or an integer offset.
    if status is not None:
        if not isinstance(status, str):
            _log("list_workspaces", "VALIDATION_ERROR", meta={"field": "status"}, started=started)
            return _err("VALIDATION_ERROR", "status must be a string", field="status")
        if status not in ("active", "suspended", "deleted"):
            _log("list_workspaces", "VALIDATION_ERROR", meta={"field": "status"}, started=started)
            return _err("VALIDATION_ERROR", "Invalid status enum value", field="status", allowed=["active", "suspended", "deleted"])

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log("list_workspaces", "VALIDATION_ERROR", meta={"field": "limit"}, started=started)
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit < 1 or limit > 100:
        _log("list_workspaces", "VALIDATION_ERROR", meta={"field": "limit"}, started=started)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")

    if sort is None:
        sort = "updated_at"
    if not isinstance(sort, str):
        _log("list_workspaces", "VALIDATION_ERROR", meta={"field": "sort"}, started=started)
        return _err("VALIDATION_ERROR", "sort must be a string", field="sort")
    if sort not in ("created_at", "updated_at", "name"):
        _log("list_workspaces", "VALIDATION_ERROR", meta={"field": "sort"}, started=started)
        return _err("VALIDATION_ERROR", "Invalid sort field", field="sort", allowed=["created_at", "updated_at", "name"])

    if order is None:
        order = "desc"
    if not isinstance(order, str):
        _log("list_workspaces", "VALIDATION_ERROR", meta={"field": "order"}, started=started)
        return _err("VALIDATION_ERROR", "order must be a string", field="order")
    if order not in ("asc", "desc"):
        _log("list_workspaces", "VALIDATION_ERROR", meta={"field": "order"}, started=started)
        return _err("VALIDATION_ERROR", "Invalid order", field="order", allowed=["asc", "desc"])

    ws = _load("workspaces.json")
    if isinstance(ws, dict) and isinstance(ws.get("rows"), list):
        ws_rows = ws.get("rows")
    elif isinstance(ws, list):
        ws_rows = ws
    else:
        ws_rows = []

    # Business rule: list_workspaces returns all workspaces where status != 'deleted' by default.
    rows = [r for r in ws_rows if isinstance(r, dict)]
    if status is None:
        rows = [r for r in rows if r.get("status") != "deleted"]
    else:
        rows = [r for r in rows if r.get("status") == status]

    def _dt_key(v):
        if not isinstance(v, str):
            return ""
        return v

    def _sort_key(r):
        if sort == "name":
            return (r.get("name") or "").lower()
        if sort == "created_at":
            return _dt_key(r.get("created_at"))
        return _dt_key(r.get("updated_at"))

    reverse = (order == "desc")
    try:
        rows.sort(key=_sort_key, reverse=reverse)
    except Exception:
        # If a row has malformed fields, keep deterministic order.
        rows = sorted(rows, key=lambda r: (r.get("id") or ""))

    total = len(rows)

    start_index = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _log("list_workspaces", "VALIDATION_ERROR", meta={"field": "cursor"}, started=started)
            return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
        # Accept: integer offset string OR workspace id (as observed in audit) meaning "start after this id in sorted set"
        if cursor.isdigit():
            start_index = int(cursor)
            if start_index < 0 or start_index > total:
                _log("list_workspaces", "VALIDATION_ERROR", meta={"field": "cursor"}, started=started)
                return _err("VALIDATION_ERROR", "Malformed cursor", field="cursor")
        else:
            # treat as "last seen id"
            pos = None
            for i, r in enumerate(rows):
                if r.get("id") == cursor:
                    pos = i
                    break
            if pos is None:
                # Real APIs typically accept an opaque cursor; here we accept id cursor only if it exists in this result set.
                _log("list_workspaces", "VALIDATION_ERROR", meta={"field": "cursor"}, started=started)
                return _err("VALIDATION_ERROR", "Malformed cursor", field="cursor")
            start_index = pos + 1

    page = rows[start_index:start_index + limit]
    has_more = (start_index + limit) < total
    next_cursor = None
    if has_more and page:
        next_cursor = page[-1].get("id")

    _log("list_workspaces", "OK", meta={"returned": len(page), "total": total}, started=started)
    return {
        "workspaces": page,
        "page_info": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "sort": {"field": sort, "order": order},
        "filter": {"status": status},
    }

def create_issue(workspace_id, team_id, title, description=None, project_id=None, state_id=None, priority=None, estimate=None, due_date=None, labels=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0308000" if __import__("os").path.isdir("./environment_mix/0308000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be a string date-time")
        try:
            # Accept trailing Z
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            datetime.datetime.fromisoformat(s2)
            return s
        except Exception:
            raise ValueError(f"{field} must be RFC3339/ISO-8601 date-time")

    def _gen_id(prefix):
        # 20+ chars to satisfy pattern {18,}
        return prefix + secrets.token_hex(12).upper()

    t0 = time.time()
    try:
        if not isinstance(workspace_id, str) or not re.match(r"^lin_ws_[0-9A-Z]{18,}$", workspace_id):
            return _err("VALIDATION_ERROR", "workspace_id is malformed")
        if not isinstance(team_id, str) or not re.match(r"^lin_team_[0-9A-Z]{18,}$", team_id):
            return _err("VALIDATION_ERROR", "team_id is malformed")
        if not isinstance(title, str) or len(title.strip()) < 1:
            return _err("VALIDATION_ERROR", "title is required and must be non-empty")

        if description is not None and not isinstance(description, str):
            return _err("VALIDATION_ERROR", "description must be a string")
        if project_id is not None:
            if not isinstance(project_id, str) or not re.match(r"^lin_proj_[0-9A-Z]{18,}$", project_id):
                return _err("VALIDATION_ERROR", "project_id is malformed")
        if state_id is not None:
            if not isinstance(state_id, str) or not re.match(r"^lin_state_[0-9A-Z]{18,}$", state_id):
                return _err("VALIDATION_ERROR", "state_id is malformed")
        if priority is None:
            priority = 3
        if not isinstance(priority, int) or priority not in (0, 1, 2, 3, 4):
            return _err("VALIDATION_ERROR", "priority must be one of 0,1,2,3,4")
        if estimate is not None:
            if not isinstance(estimate, (int, float)):
                return _err("VALIDATION_ERROR", "estimate must be a number")
            if estimate < 0:
                return _err("VALIDATION_ERROR", "estimate must be >= 0")
        try:
            due_date = _parse_dt(due_date, "due_date")
        except ValueError as ve:
            return _err("VALIDATION_ERROR", str(ve))
        if labels is None:
            labels = []
        if not isinstance(labels, list) or any(not isinstance(x, str) for x in labels):
            return _err("VALIDATION_ERROR", "labels must be an array of strings")
    except Exception as e:
        return _err("VALIDATION_ERROR", "Invalid request", detail=str(e))

    workspaces = _load("workspaces.json")
    teams = _load("teams.json")
    states = _load("workflow_states.json")
    projects = _load("projects.json")
    issues = _load("issues.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        return _err("INVALID_TRANSITION", "Workspace is not active", workspace_status=ws.get("status"))

    team = next((t for t in teams if isinstance(t, dict) and t.get("id") == team_id), None)
    if team is None:
        return _err("NOT_FOUND", "Team not found")
    if team.get("workspace_id") != workspace_id:
        return _err("VALIDATION_ERROR", "team_id does not belong to workspace_id")
    if team.get("status") != "active":
        return _err("INVALID_TRANSITION", "Team is not active", team_status=team.get("status"))

    proj = None
    if project_id is not None:
        proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
        if proj is None:
            return _err("NOT_FOUND", "Project not found")
        if proj.get("workspace_id") != workspace_id:
            return _err("VALIDATION_ERROR", "project_id does not belong to workspace_id")
        # archived projects still exist; allowed association unless rules forbid; schema doesn't forbid

    chosen_state = None
    if state_id is not None:
        chosen_state = next((s for s in states if isinstance(s, dict) and s.get("id") == state_id), None)
        if chosen_state is None:
            return _err("NOT_FOUND", "Workflow state not found")
        if chosen_state.get("team_id") != team_id:
            return _err("VALIDATION_ERROR", "state_id does not belong to team_id")
        if chosen_state.get("status") != "active":
            return _err("INVALID_TRANSITION", "Workflow state is not active", state_status=chosen_state.get("status"))
    else:
        defaults = [s for s in states if isinstance(s, dict) and s.get("team_id") == team_id and s.get("status") == "active" and s.get("is_default") is True]
        if len(defaults) != 1:
            return _err("CONFLICT", "Team must have exactly one active default workflow state", found=len(defaults))
        chosen_state = defaults[0]
        state_id = chosen_state.get("id")

    # Allocate next number per team atomically within this single-process store: compute max+1
    existing_numbers = [i.get("number") for i in issues if isinstance(i, dict) and i.get("team_id") == team_id and isinstance(i.get("number"), int)]
    next_number = (max(existing_numbers) + 1) if existing_numbers else 1

    identifier = f"{team.get('key')}-{next_number}"

    # Uniqueness checks
    if any(isinstance(i, dict) and i.get("team_id") == team_id and i.get("number") == next_number for i in issues):
        return _err("CONFLICT", "Issue number already exists for team", team_id=team_id, number=next_number)
    if any(isinstance(i, dict) and i.get("team_id") == team_id and i.get("identifier") == identifier for i in issues):
        return _err("CONFLICT", "Issue identifier already exists for team", team_id=team_id, identifier=identifier)

    now = _now()
    new_issue = {
        "id": _gen_id("lin_issue_"),
        "workspace_id": workspace_id,
        "team_id": team_id,
        "project_id": project_id,
        "state_id": state_id,
        "identifier": identifier,
        "number": next_number,
        "title": title,
        "description": description,
        "priority": int(priority),
        "estimate": float(estimate) if isinstance(estimate, (int, float)) else None,
        "due_date": due_date,
        "labels": list(labels),
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    issues.append(new_issue)
    try:
        _save("issues.json", issues)
    except Exception as e:
        return _err("CONFLICT", "Failed to persist issue", detail=str(e))

    return {"data": new_issue}

def list_issues(workspace_id=None, team_id=None, project_id=None, state_id=None, priority=None, status=None, identifier=None, number=None, label=None, created_after=None, created_before=None, updated_after=None, updated_before=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0308000" if __import__("os").path.isdir("./environment_mix/0308000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be a string date-time")
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            raise ValueError(f"{field} must be RFC3339/ISO-8601 date-time")

    t0 = time.time()
    try:
        if workspace_id is not None and (not isinstance(workspace_id, str) or not re.match(r"^lin_ws_[0-9A-Z]{18,}$", workspace_id)):
            return _err("VALIDATION_ERROR", "workspace_id is malformed")
        if team_id is not None and (not isinstance(team_id, str) or not re.match(r"^lin_team_[0-9A-Z]{18,}$", team_id)):
            return _err("VALIDATION_ERROR", "team_id is malformed")
        if project_id is not None and (not isinstance(project_id, str) or not re.match(r"^lin_proj_[0-9A-Z]{18,}$", project_id)):
            return _err("VALIDATION_ERROR", "project_id is malformed")
        if state_id is not None and (not isinstance(state_id, str) or not re.match(r"^lin_state_[0-9A-Z]{18,}$", state_id)):
            return _err("VALIDATION_ERROR", "state_id is malformed")

        if priority is not None:
            if not isinstance(priority, int) or priority not in (0, 1, 2, 3, 4):
                return _err("VALIDATION_ERROR", "priority must be one of 0,1,2,3,4")
        if status is not None:
            if not isinstance(status, str) or status not in ("active", "deleted"):
                return _err("VALIDATION_ERROR", "status must be 'active' or 'deleted'")
        if identifier is not None and not isinstance(identifier, str):
            return _err("VALIDATION_ERROR", "identifier must be a string")
        if number is not None:
            if not isinstance(number, int) or number < 1:
                return _err("VALIDATION_ERROR", "number must be an integer >= 1")
        if label is not None and not isinstance(label, str):
            return _err("VALIDATION_ERROR", "label must be a string")

        try:
            ca = _parse_dt(created_after, "created_after")
            cb = _parse_dt(created_before, "created_before")
            ua = _parse_dt(updated_after, "updated_after")
            ub = _parse_dt(updated_before, "updated_before")
        except ValueError as ve:
            return _err("VALIDATION_ERROR", str(ve))

        if limit is None:
            limit = 50
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100")

        if sort is None:
            sort = "updated_at"
        if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "due_date", "priority", "number"):
            return _err("VALIDATION_ERROR", "Invalid sort field", allowed=["created_at", "updated_at", "due_date", "priority", "number"])

        if order is None:
            order = "desc"
        if not isinstance(order, str) or order not in ("asc", "desc"):
            return _err("VALIDATION_ERROR", "Invalid order", allowed=["asc", "desc"])

        start = 0
        # Cursor includes filters signature to prevent misuse
        if cursor is not None:
            if not isinstance(cursor, str):
                return _err("VALIDATION_ERROR", "cursor must be a string")
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
                payload = json.loads(raw.decode("utf-8"))
                if not isinstance(payload, dict) or payload.get("v") != 1:
                    return _err("VALIDATION_ERROR", "Malformed cursor")
                start = payload.get("o")
                if not isinstance(start, int) or start < 0:
                    return _err("VALIDATION_ERROR", "Malformed cursor")
                sig = payload.get("q")
                expected_sig = {
                    "workspace_id": workspace_id,
                    "team_id": team_id,
                    "project_id": project_id,
                    "state_id": state_id,
                    "priority": priority,
                    "status": status,
                    "identifier": identifier,
                    "number": number,
                    "label": label,
                    "created_after": created_after,
                    "created_before": created_before,
                    "updated_after": updated_after,
                    "updated_before": updated_before,
                    "sort": sort,
                    "order": order,
                }
                if sig != expected_sig:
                    return _err("VALIDATION_ERROR", "Cursor does not match query parameters")
            except Exception:
                return _err("VALIDATION_ERROR", "Malformed cursor")
    except Exception as e:
        return _err("VALIDATION_ERROR", "Invalid request", detail=str(e))

    issues = _load("issues.json")

    # Default: only active
    eff_status = status if status is not None else "active"

    def _get_dt(issue, field):
        v = issue.get(field)
        if not isinstance(v, str):
            return None
        try:
            s2 = v[:-1] + "+00:00" if v.endswith("Z") else v
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    filtered = []
    for i in issues:
        if not isinstance(i, dict):
            continue
        if eff_status is not None and i.get("status") != eff_status:
            continue
        if workspace_id is not None and i.get("workspace_id") != workspace_id:
            continue
        if team_id is not None and i.get("team_id") != team_id:
            continue
        if project_id is not None and i.get("project_id") != project_id:
            continue
        if state_id is not None and i.get("state_id") != state_id:
            continue
        if priority is not None and i.get("priority") != priority:
            continue
        if identifier is not None and i.get("identifier") != identifier:
            continue
        if number is not None and i.get("number") != number:
            continue
        if label is not None:
            labs = i.get("labels")
            if not isinstance(labs, list) or label not in labs:
                continue
        if ca is not None:
            cdt = _get_dt(i, "created_at")
            if cdt is None or cdt <= ca:
                continue
        if cb is not None:
            cdt = _get_dt(i, "created_at")
            if cdt is None or cdt >= cb:
                continue
        if ua is not None:
            udt = _get_dt(i, "updated_at")
            if udt is None or udt <= ua:
                continue
        if ub is not None:
            udt = _get_dt(i, "updated_at")
            if udt is None or udt >= ub:
                continue
        filtered.append(i)

    reverse = (order == "desc")

    def _key_dt(s):
        if s is None:
            return ""
        if isinstance(s, str):
            return s
        return str(s)

    def _key_due(issue):
        # Put None last for asc, first for desc
        v = issue.get("due_date")
        is_none = (v is None)
        k = _key_dt(v)
        return (is_none, k)

    if sort in ("created_at", "updated_at"):
        filtered.sort(key=lambda r: (_key_dt(r.get(sort)), str(r.get("id", ""))), reverse=reverse)
    elif sort == "due_date":
        filtered.sort(key=lambda r: (_key_due(r), _key_dt(r.get("updated_at")), str(r.get("id", ""))), reverse=reverse)
    elif sort == "priority":
        filtered.sort(key=lambda r: (r.get("priority", 999), _key_dt(r.get("updated_at")), str(r.get("id", ""))), reverse=reverse)
    elif sort == "number":
        filtered.sort(key=lambda r: (r.get("number", 0), str(r.get("id", ""))), reverse=reverse)

    total = len(filtered)
    page = filtered[start:start + limit]
    has_more = (start + limit) < total
    next_cursor = None
    if has_more:
        payload = {
            "v": 1,
            "o": start + limit,
            "q": {
                "workspace_id": workspace_id,
                "team_id": team_id,
                "project_id": project_id,
                "state_id": state_id,
                "priority": priority,
                "status": status,
                "identifier": identifier,
                "number": number,
                "label": label,
                "created_after": created_after,
                "created_before": created_before,
                "updated_after": updated_after,
                "updated_before": updated_before,
                "sort": sort,
                "order": order,
            },
        }
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
            "default_status": eff_status,
        },
    }

def update_issue(issue_id, title=None, description=None, project_id=None, team_id=None, state_id=None, priority=None, estimate=None, due_date=None, labels=None, status=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0308000" if __import__("os").path.isdir("./environment_mix/0308000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    endpoint = "update_issue"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log(status_code, workspace_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - started) * 1000)
        row = {
            "id": f"lin_req_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}",
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": latency_ms,
            "credential_id": None,
            "workspace_id": workspace_id,
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a string date-time", field=field)
        s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
        try:
            datetime.datetime.fromisoformat(s2)
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be RFC3339/ISO-8601 date-time", field=field)
        return s, None  # store as provided string

    def _rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    # Validate inputs
    if not isinstance(issue_id, str) or not issue_id:
        _log("VALIDATION_ERROR", meta={"field": "issue_id"})
        return _err("VALIDATION_ERROR", "issue_id must be a non-empty string", field="issue_id")

    # Do not over-reject by pattern (audit showed callers may send other ids); but still validate other fields strongly.
    if title is not None and (not isinstance(title, str) or len(title) < 1):
        _log("VALIDATION_ERROR", meta={"field": "title"})
        return _err("VALIDATION_ERROR", "title must be a non-empty string", field="title")

    if description is not None and not isinstance(description, str):
        _log("VALIDATION_ERROR", meta={"field": "description"})
        return _err("VALIDATION_ERROR", "description must be a string", field="description")

    if project_id is not None:
        if not isinstance(project_id, str):
            _log("VALIDATION_ERROR", meta={"field": "project_id"})
            return _err("VALIDATION_ERROR", "project_id must be a string", field="project_id")
        if not re.match(r"^lin_proj_[0-9A-Z]{18,}$", project_id):
            _log("VALIDATION_ERROR", meta={"field": "project_id"})
            return _err("VALIDATION_ERROR", "project_id is not a valid id", field="project_id")

    if team_id is not None:
        if not isinstance(team_id, str):
            _log("VALIDATION_ERROR", meta={"field": "team_id"})
            return _err("VALIDATION_ERROR", "team_id must be a string", field="team_id")
        if not re.match(r"^lin_team_[0-9A-Z]{18,}$", team_id):
            _log("VALIDATION_ERROR", meta={"field": "team_id"})
            return _err("VALIDATION_ERROR", "team_id is not a valid id", field="team_id")

    if state_id is not None:
        if not isinstance(state_id, str):
            _log("VALIDATION_ERROR", meta={"field": "state_id"})
            return _err("VALIDATION_ERROR", "state_id must be a string", field="state_id")
        if not re.match(r"^lin_state_[0-9A-Z]{18,}$", state_id):
            _log("VALIDATION_ERROR", meta={"field": "state_id"})
            return _err("VALIDATION_ERROR", "state_id is not a valid id", field="state_id")

    if priority is not None:
        if not isinstance(priority, int) or priority not in (0, 1, 2, 3, 4):
            _log("VALIDATION_ERROR", meta={"field": "priority"})
            return _err("VALIDATION_ERROR", "priority must be an integer in [0,1,2,3,4]", field="priority")

    if estimate is not None:
        if not isinstance(estimate, (int, float)):
            _log("VALIDATION_ERROR", meta={"field": "estimate"})
            return _err("VALIDATION_ERROR", "estimate must be a number", field="estimate")
        if float(estimate) < 0:
            _log("VALIDATION_ERROR", meta={"field": "estimate"})
            return _err("VALIDATION_ERROR", "estimate must be >= 0", field="estimate")

    if due_date is not None:
        _, e = _parse_dt(due_date, "due_date")
        if e:
            _log("VALIDATION_ERROR", meta={"field": "due_date"})
            return e

    if labels is not None:
        if not isinstance(labels, list) or any(not isinstance(x, str) for x in labels):
            _log("VALIDATION_ERROR", meta={"field": "labels"})
            return _err("VALIDATION_ERROR", "labels must be an array of strings", field="labels")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            _log("VALIDATION_ERROR", meta={"field": "status"})
            return _err("VALIDATION_ERROR", "status must be one of: active, deleted", field="status")

    issues_data = _load("issues.json")
    issue_rows = _rows(issues_data)

    issue_idx = None
    issue = None
    for i, r in enumerate(issue_rows):
        if isinstance(r, dict) and r.get("id") == issue_id:
            issue = r
            issue_idx = i
            break

    if issue is None:
        _log("NOT_FOUND", meta={"issue_id": issue_id})
        return _err("NOT_FOUND", "Issue not found", issue_id=issue_id)

    # Deleted issues cannot be updated (no restore via this surface)
    if issue.get("status") == "deleted":
        _log("INVALID_TRANSITION", workspace_id=issue.get("workspace_id"), meta={"issue_id": issue_id})
        return _err("INVALID_TRANSITION", "Deleted issues cannot be updated", issue_id=issue_id)

    # Must have at least one field to update
    if all(v is None for v in (title, description, project_id, team_id, state_id, priority, estimate, due_date, labels, status)):
        _log("VALIDATION_ERROR", workspace_id=issue.get("workspace_id"), meta={"issue_id": issue_id})
        return _err("VALIDATION_ERROR", "No fields provided to update", issue_id=issue_id)

    # Load referenced collections for validation
    teams = _rows(_load("teams.json"))
    wss = _rows(_load("workspaces.json"))
    projs = _rows(_load("projects.json"))
    states = _rows(_load("workflow_states.json"))

    def _find_by_id(rows, _id):
        for rr in rows:
            if isinstance(rr, dict) and rr.get("id") == _id:
                return rr
        return None

    current_team = _find_by_id(teams, issue.get("team_id"))
    current_ws = _find_by_id(wss, issue.get("workspace_id"))

    # Cross-reference sanity: existing issue should be consistent; if not, treat as conflict.
    if current_team is None:
        _log("CONFLICT", workspace_id=issue.get("workspace_id"), meta={"issue_id": issue_id})
        return _err("CONFLICT", "Issue references missing team", issue_id=issue_id, team_id=issue.get("team_id"))
    if current_ws is None:
        _log("CONFLICT", workspace_id=issue.get("workspace_id"), meta={"issue_id": issue_id})
        return _err("CONFLICT", "Issue references missing workspace", issue_id=issue_id, workspace_id=issue.get("workspace_id"))
    if current_team.get("workspace_id") != issue.get("workspace_id"):
        _log("CONFLICT", workspace_id=issue.get("workspace_id"), meta={"issue_id": issue_id})
        return _err("CONFLICT", "Issue workspace_id must match team.workspace_id", issue_id=issue_id)

    # Determine target team/workspace (team move changes workspace context to target team workspace)
    target_team = current_team
    target_workspace = current_ws

    if team_id is not None and team_id != current_team.get("id"):
        t = _find_by_id(teams, team_id)
        if t is None:
            _log("NOT_FOUND", workspace_id=issue.get("workspace_id"), meta={"field": "team_id"})
            return _err("NOT_FOUND", "Team not found", team_id=team_id)
        # enforce business rule for create; for update, still enforce that moving to inactive team isn't allowed
        if t.get("status") != "active":
            _log("CONFLICT", workspace_id=issue.get("workspace_id"), meta={"field": "team_id"})
            return _err("CONFLICT", "Cannot move issue to a non-active team", team_id=team_id, team_status=t.get("status"))
        ws = _find_by_id(wss, t.get("workspace_id"))
        if ws is None:
            _log("CONFLICT", workspace_id=issue.get("workspace_id"), meta={"field": "team_id"})
            return _err("CONFLICT", "Target team references missing workspace", team_id=team_id, workspace_id=t.get("workspace_id"))
        if ws.get("status") != "active":
            _log("CONFLICT", workspace_id=ws.get("id"), meta={"field": "team_id"})
            return _err("CONFLICT", "Cannot move issue to a non-active workspace", workspace_id=ws.get("id"), workspace_status=ws.get("status"))
        target_team = t
        target_workspace = ws

    # Validate target state belongs to target team (if state_id is provided OR team changes and state not provided -> keep but must be valid for new team)
    target_state_id = state_id if state_id is not None else issue.get("state_id")
    if target_state_id is not None:
        st = _find_by_id(states, target_state_id)
        if st is None:
            _log("NOT_FOUND", workspace_id=target_workspace.get("id"), meta={"field": "state_id"})
            return _err("NOT_FOUND", "Workflow state not found", state_id=target_state_id)
        if st.get("team_id") != target_team.get("id"):
            _log("CONFLICT", workspace_id=target_workspace.get("id"), meta={"field": "state_id"})
            return _err("CONFLICT", "state_id must belong to the same team as the issue", state_id=target_state_id, team_id=target_team.get("id"))

    # Validate project workspace consistency
    target_project_id = project_id if project_id is not None else issue.get("project_id")
    if target_project_id is not None:
        pr = _find_by_id(projs, target_project_id)
        if pr is None:
            _log("NOT_FOUND", workspace_id=target_workspace.get("id"), meta={"field": "project_id"})
            return _err("NOT_FOUND", "Project not found", project_id=target_project_id)
        if pr.get("workspace_id") != target_workspace.get("id"):
            _log("CONFLICT", workspace_id=target_workspace.get("id"), meta={"field": "project_id"})
            return _err("CONFLICT", "project_id must belong to the same workspace as the issue", project_id=target_project_id, workspace_id=target_workspace.get("id"))

    # Lifecycle transition validation for issue.status
    if status is not None and status != issue.get("status"):
        if issue.get("status") == "active" and status == "deleted":
            pass
        else:
            _log("INVALID_TRANSITION", workspace_id=target_workspace.get("id"), meta={"field": "status"})
            return _err("INVALID_TRANSITION", f"Cannot transition issue status from {issue.get('status')} to {status}", issue_id=issue_id)

    # Apply update atomically
    updated = dict(issue)
    if team_id is not None and team_id != issue.get("team_id"):
        # When moving teams, number/identifier must be reallocated to maintain unique(team_id, number/identifier)
        existing_numbers = set()
        existing_identifiers = set()
        max_num = 0
        for r in issue_rows:
            if not isinstance(r, dict):
                continue
            if r.get("team_id") == target_team.get("id"):
                n = r.get("number")
                if isinstance(n, int):
                    existing_numbers.add(n)
                    if n > max_num:
                        max_num = n
                ident = r.get("identifier")
                if isinstance(ident, str):
                    existing_identifiers.add(ident)

        new_num = max_num + 1
        # ensure no gaps collisions (defensive)
        while new_num in existing_numbers:
            new_num += 1
        new_ident = f"{target_team.get('key')}-{new_num}"
        # extremely defensive
        while new_ident in existing_identifiers:
            new_num += 1
            new_ident = f"{target_team.get('key')}-{new_num}"

        updated["team_id"] = target_team.get("id")
        updated["workspace_id"] = target_workspace.get("id")
        updated["number"] = new_num
        updated["identifier"] = new_ident

    if title is not None:
        updated["title"] = title
    if description is not None:
        updated["description"] = description
    if priority is not None:
        updated["priority"] = priority
    if estimate is not None:
        updated["estimate"] = estimate
    if due_date is not None:
        updated["due_date"] = due_date
    if labels is not None:
        updated["labels"] = labels
    if project_id is not None:
        updated["project_id"] = project_id
    if state_id is not None:
        updated["state_id"] = state_id
    if status is not None:
        updated["status"] = status

    updated["updated_at"] = _now_iso()

    issue_rows[issue_idx] = updated
    if isinstance(issues_data, dict) and isinstance(issues_data.get("rows"), list):
        issues_data["rows"] = issue_rows
        _save("issues.json", issues_data)
    else:
        _save("issues.json", issue_rows)

    _log("OK", workspace_id=updated.get("workspace_id"), meta={"issue_id": issue_id})
    return {"issue": updated}

def get_issue_status(team_id, status=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0308000" if __import__("os").path.isdir("./environment_mix/0308000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_code, message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"lin_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status_code,
            "message": message,
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    start = time.time()
    endpoint = "get_issue_status"

    try:
        if not isinstance(team_id, str) or not re.match(r"^lin_team_[0-9A-Z]{18,}$", team_id):
            _log(endpoint, "VALIDATION_ERROR", "Malformed team_id", {"team_id": team_id})
            return _err("VALIDATION_ERROR", "Malformed team_id", field="team_id")

        if status is not None:
            if not isinstance(status, str) or status not in ("active", "deprecated"):
                _log(endpoint, "VALIDATION_ERROR", "Invalid status filter", {"status": status})
                return _err("VALIDATION_ERROR", "Invalid status filter", field="status")

        teams = _load("teams.json")
        team = next((t for t in teams if isinstance(t, dict) and t.get("id") == team_id), None)
        if not team:
            _log(endpoint, "NOT_FOUND", "Team not found", {"team_id": team_id})
            return _err("NOT_FOUND", "Team not found")

        states = _load("workflow_states.json")
        rows = [s for s in states if isinstance(s, dict) and s.get("team_id") == team_id]

        # Default behavior: only active
        if status is None:
            rows = [s for s in rows if s.get("status") == "active"]
        else:
            rows = [s for s in rows if s.get("status") == status]

        def _pos(v):
            try:
                return float(v)
            except Exception:
                return 1e18

        rows.sort(key=lambda s: (_pos(s.get("position")), str(s.get("id", ""))))

        out = []
        for s in rows:
            out.append(
                {
                    "id": s.get("id"),
                    "name": s.get("name"),
                    "description": s.get("description"),
                    "position": s.get("position"),
                    "type": s.get("type"),
                    "status": s.get("status"),
                    "is_default": s.get("is_default"),
                    "is_resolved": s.get("is_resolved"),
                    "created_at": s.get("created_at"),
                    "updated_at": s.get("updated_at"),
                }
            )

        _log(endpoint, "OK", meta={"team_id": team_id, "count": len(out), "latency_ms": int((time.time() - start) * 1000)})
        return {"data": {"team_id": team_id, "workflow_states": out, "count": len(out)}}
    except Exception as e:
        _log(endpoint, "ERROR", "Internal error", {"detail": str(e)})
        return _err("CONFLICT", "Internal error")

def list_teams(workspace_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0308000" if __import__("os").path.isdir("./environment_mix/0308000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_code, message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"lin_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status_code,
            "message": message,
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c:
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===").decode("utf-8")
            if raw.startswith("offset:"):
                return int(raw.split(":", 1)[1])
            return None
        except Exception:
            return None

    def _make_cursor(off):
        raw = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    start = time.time()
    endpoint = "list_teams"

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^lin_ws_[0-9A-Z]{18,}$", workspace_id):
            _log(endpoint, "VALIDATION_ERROR", "Malformed workspace_id", {"workspace_id": workspace_id})
            return _err("VALIDATION_ERROR", "Malformed workspace_id", field="workspace_id")

        if status is not None:
            if not isinstance(status, str) or status not in ("active", "archived"):
                _log(endpoint, "VALIDATION_ERROR", "Invalid status", {"status": status})
                return _err("VALIDATION_ERROR", "Invalid status", field="status")

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            _log(endpoint, "VALIDATION_ERROR", "limit out of range", {"limit": limit})
            return _err("VALIDATION_ERROR", "limit out of range", field="limit")

        if sort is None:
            sort = "updated_at"
        if sort not in ("created_at", "updated_at", "name", "key"):
            _log(endpoint, "VALIDATION_ERROR", "Invalid sort field", {"sort": sort})
            return _err("VALIDATION_ERROR", "Invalid sort field", field="sort")

        if order is None:
            order = "asc"
        if order not in ("asc", "desc"):
            _log(endpoint, "VALIDATION_ERROR", "Invalid order", {"order": order})
            return _err("VALIDATION_ERROR", "Invalid order", field="order")

        off = _parse_cursor(cursor)
        if off is None:
            _log(endpoint, "VALIDATION_ERROR", "Invalid cursor", {"cursor": cursor})
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

        workspaces = _load("workspaces.json")
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not ws or ws.get("status") == "deleted":
            _log(endpoint, "NOT_FOUND", "Workspace not found", {"workspace_id": workspace_id})
            return _err("NOT_FOUND", "Workspace not found")

        teams = _load("teams.json")
        rows = [t for t in teams if isinstance(t, dict) and t.get("workspace_id") == workspace_id]

        # Business rule: exclude archived unless explicit include_archived exists (it does not)
        if status is None:
            rows = [t for t in rows if t.get("status") != "archived"]
        else:
            rows = [t for t in rows if t.get("status") == status]

        def _dt(v):
            if not v:
                return datetime.datetime.min
            if isinstance(v, str):
                s = v[:-1] if v.endswith("Z") else v
                try:
                    return datetime.datetime.fromisoformat(s)
                except Exception:
                    return datetime.datetime.min
            return datetime.datetime.min

        def _k(t):
            if sort in ("created_at", "updated_at"):
                return _dt(t.get(sort))
            return (t.get(sort) or "").lower()

        reverse = (order == "desc")
        rows.sort(key=lambda t: (_k(t), str(t.get("id", ""))), reverse=reverse)

        total = len(rows)
        page = rows[off:off + limit]
        next_off = off + len(page)
        has_more = next_off < total
        next_cursor = _make_cursor(next_off) if has_more else None

        _log(
            endpoint,
            "OK",
            meta={
                "workspace_id": workspace_id,
                "returned": len(page),
                "total": total,
                "offset": off,
                "latency_ms": int((time.time() - start) * 1000),
            },
        )
        return {
            "data": {
                "teams": page,
                "page_info": {"limit": limit, "total": total, "has_more": has_more, "next_cursor": next_cursor},
            }
        }
    except Exception as e:
        _log(endpoint, "ERROR", "Internal error", {"detail": str(e)})
        return _err("CONFLICT", "Internal error")

