    endpoint = "list_projects"

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^lin_ws_[0-9A-Z]{18,}$", workspace_id):
            _log(endpoint, "VALIDATION_ERROR", "Malformed workspace_id", {"workspace_id": workspace_id})
            return _err("VALIDATION_ERROR", "Malformed workspace_id", field="workspace_id")

        if status is not None:
            if not isinstance(status, str) or status not in ("planned", "started", "paused", "completed", "canceled", "archived"):
                _log(endpoint, "VALIDATION_ERROR", "Invalid status", {"status": status})
                return _err("VALIDATION_ERROR", "Invalid status", field="status")

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            _log(endpoint, "VALIDATION_ERROR", "limit out of range", {"limit": limit})
            return _err("VALIDATION_ERROR", "limit out of range", field="limit")

        if sort is None:
            sort = "updated_at"
        if sort not in ("created_at", "updated_at", "name", "start_date", "target_date"):
            _log(endpoint, "VALIDATION_ERROR", "Invalid sort field", {"sort": sort})
            return _err("VALIDATION_ERROR", "Invalid sort field", field="sort")

        if order is None:
            order = "desc"
        if order not in ("asc", "desc"):
            _log(endpoint, "VALIDATION_ERROR", "Invalid order", {"order": order})
            return _err("VALIDATION_ERROR", "Invalid order", field="order")

        off = _parse_cursor(cursor)
        if off is None:
            _log(endpoint, "VALIDATION_ERROR", "Invalid cursor", {"cursor": cursor})
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

        sa = _parse_dt(start_after, "start_after")
        sb = _parse_dt(start_before, "start_before")
        ta = _parse_dt(target_after, "target_after")
        tb = _parse_dt(target_before, "target_before")
        for v in (sa, sb, ta, tb):
            if isinstance(v, tuple) and v and v[0] == "ERR":
                _log(endpoint, "VALIDATION_ERROR", "Invalid date-time", {"field": v[1]})
                return _err("VALIDATION_ERROR", "Invalid date-time", field=v[1])

        workspaces = _load("workspaces.json")
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not ws or ws.get("status") == "deleted":
            _log(endpoint, "NOT_FOUND", "Workspace not found", {"workspace_id": workspace_id})
            return _err("NOT_FOUND", "Workspace not found")

        projects = _load("projects.json")
        rows = [p for p in projects if isinstance(p, dict) and p.get("workspace_id") == workspace_id]

        # Exclude archived by default
        if status is None:
            rows = [p for p in rows if p.get("status") != "archived"]
        else:
            rows = [p for p in rows if p.get("status") == status]

        def _in_range(dt_val, after, before):
            if dt_val is None:
                return False
            if after is not None and dt_val <= after:
                return False
            if before is not None and dt_val >= before:
                return False
            return True

        if sa is not None or sb is not None:
            rows = [p for p in rows if _in_range(_dt(p.get("start_date")), sa, sb)]
        if ta is not None or tb is not None:
            rows = [p for p in rows if _in_range(_dt(p.get("target_date")), ta, tb)]

        reverse = (order == "desc")

        if status is None and sort is None:
            # not used; kept for clarity
            pass

        # Business rule default ordering: updated_at desc then created_at desc
        if sort == "updated_at" and order == "desc":
            rows.sort(key=lambda p: (_dt(p.get("updated_at")) or datetime.datetime.min, _dt(p.get("created_at")) or datetime.datetime.min, str(p.get("id", ""))), reverse=True)
        else:
            def _key(p):
                if sort in ("created_at", "updated_at", "start_date", "target_date"):
                    return _dt(p.get(sort)) or datetime.datetime.min
                return (p.get("name") or "").lower()
            rows.sort(key=lambda p: (_key(p), str(p.get("id", ""))), reverse=reverse)

        total = len(rows)
        page = rows[off:off + limit]
        next_off = off + len(page)
        has_more = next_off < total
        next_cursor = _make_cursor(next_off) if has_more else None

        _log(
            endpoint,
            "OK",
            meta={
                "workspace_id": workspace_id,
                "returned": len(page),
                "total": total,
                "offset": off,
                "latency_ms": int((time.time() - start) * 1000),
            },
        )
        return {"data": {"projects": page, "page_info": {"limit": limit, "total": total, "has_more": has_more, "next_cursor": next_cursor}}}
    except Exception as e:
        _log(endpoint, "ERROR", "Internal error", {"detail": str(e)})
        return _err("CONFLICT", "Internal error")

def search_issues(query, workspace_id=None, team_id=None, project_id=None, state_id=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0308000" if __import__("os").path.isdir("./environment_mix/0308000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_code, message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"lin_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status_code,
            "message": message,
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c:
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===").decode("utf-8")
            if raw.startswith("offset:"):
                return int(raw.split(":", 1)[1])
            return None
        except Exception:
            return None

    def _make_cursor(off):
        raw = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _dt(v):
        if not v:
            return datetime.datetime.min
        if isinstance(v, str):
            s = v[:-1] if v.endswith("Z") else v
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return datetime.datetime.min
        return datetime.datetime.min

    def _tokenize(s):
        s = (s or "").lower()
        parts = re.findall(r"[a-z0-9]+", s)
        return [p for p in parts if p]

    start = time.time()
    endpoint = "search_issues"

    try:
        if not isinstance(query, str) or len(query.strip()) < 1:
            _log(endpoint, "VALIDATION_ERROR", "query must be a non-empty string", {"query": query})
            return _err("VALIDATION_ERROR", "query must be a non-empty string", field="query")

        if workspace_id is not None:
            if not isinstance(workspace_id, str) or not re.match(r"^lin_ws_[0-9A-Z]{18,}$", workspace_id):
                _log(endpoint, "VALIDATION_ERROR", "Malformed workspace_id", {"workspace_id": workspace_id})
                return _err("VALIDATION_ERROR", "Malformed workspace_id", field="workspace_id")

        if team_id is not None:
            if not isinstance(team_id, str) or not re.match(r"^lin_team_[0-9A-Z]{18,}$", team_id):
                _log(endpoint, "VALIDATION_ERROR", "Malformed team_id", {"team_id": team_id})
                return _err("VALIDATION_ERROR", "Malformed team_id", field="team_id")

        if project_id is not None:
            if not isinstance(project_id, str) or not re.match(r"^lin_proj_[0-9A-Z]{18,}$", project_id):
                _log(endpoint, "VALIDATION_ERROR", "Malformed project_id", {"project_id": project_id})
                return _err("VALIDATION_ERROR", "Malformed project_id", field="project_id")

        if state_id is not None:
            if not isinstance(state_id, str) or not re.match(r"^lin_state_[0-9A-Z]{18,}$", state_id):
                _log(endpoint, "VALIDATION_ERROR", "Malformed state_id", {"state_id": state_id})
                return _err("VALIDATION_ERROR", "Malformed state_id", field="state_id")

        if status is not None:
            if not isinstance(status, str) or status not in ("active", "deleted"):
                _log(endpoint, "VALIDATION_ERROR", "Invalid status", {"status": status})
                return _err("VALIDATION_ERROR", "Invalid status", field="status")

        if limit is None:
            limit = 20
        if not isinstance(limit, int) or limit < 1 or limit > 50:
            _log(endpoint, "VALIDATION_ERROR", "limit out of range", {"limit": limit})
            return _err("VALIDATION_ERROR", "limit out of range", field="limit")

        off = _parse_cursor(cursor)
        if off is None:
            _log(endpoint, "VALIDATION_ERROR", "Invalid cursor", {"cursor": cursor})
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

        # Validate references when provided
        teams = _load("teams.json")
        workspaces = _load("workspaces.json")
        projects = _load("projects.json")
        states = _load("workflow_states.json")

        if workspace_id is not None:
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id and w.get("status") != "deleted"), None)
            if not ws:
                _log(endpoint, "NOT_FOUND", "Workspace not found", {"workspace_id": workspace_id})
                return _err("NOT_FOUND", "Workspace not found")

        if team_id is not None:
            t = next((t for t in teams if isinstance(t, dict) and t.get("id") == team_id), None)
            if not t:
                _log(endpoint, "NOT_FOUND", "Team not found", {"team_id": team_id})
                return _err("NOT_FOUND", "Team not found")
            if workspace_id is not None and t.get("workspace_id") != workspace_id:
                _log(endpoint, "VALIDATION_ERROR", "team_id not in workspace", {"team_id": team_id, "workspace_id": workspace_id})
                return _err("VALIDATION_ERROR", "team_id not in workspace", field="team_id")

        if project_id is not None:
            p = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
            if not p:
                _log(endpoint, "NOT_FOUND", "Project not found", {"project_id": project_id})
                return _err("NOT_FOUND", "Project not found")
            if workspace_id is not None and p.get("workspace_id") != workspace_id:
                _log(endpoint, "VALIDATION_ERROR", "project_id not in workspace", {"project_id": project_id, "workspace_id": workspace_id})
                return _err("VALIDATION_ERROR", "project_id not in workspace", field="project_id")
            if team_id is not None and p.get("workspace_id") != next((tt.get("workspace_id") for tt in teams if tt.get("id") == team_id), None):
                _log(endpoint, "VALIDATION_ERROR", "project_id not in team workspace", {"project_id": project_id, "team_id": team_id})
                return _err("VALIDATION_ERROR", "project_id not in team workspace", field="project_id")

        if state_id is not None:
            s = next((s for s in states if isinstance(s, dict) and s.get("id") == state_id), None)
            if not s:
                _log(endpoint, "NOT_FOUND", "Workflow state not found", {"state_id": state_id})
                return _err("NOT_FOUND", "Workflow state not found")
            if team_id is not None and s.get("team_id") != team_id:
                _log(endpoint, "VALIDATION_ERROR", "state_id not in team", {"state_id": state_id, "team_id": team_id})
                return _err("VALIDATION_ERROR", "state_id not in team", field="state_id")

        issues = _load("issues.json")
        rows = [i for i in issues if isinstance(i, dict)]

        # Default: active only
        if status is None:
            rows = [i for i in rows if i.get("status") == "active"]
        else:
            rows = [i for i in rows if i.get("status") == status]

        if workspace_id is not None:
            rows = [i for i in rows if i.get("workspace_id") == workspace_id]
        if team_id is not None:
            rows = [i for i in rows if i.get("team_id") == team_id]
        if project_id is not None:
            rows = [i for i in rows if i.get("project_id") == project_id]
        if state_id is not None:
            rows = [i for i in rows if i.get("state_id") == state_id]

        q_tokens = _tokenize(query)
        if not q_tokens:
            _log(endpoint, "VALIDATION_ERROR", "query must contain searchable characters", {"query": query})
            return _err("VALIDATION_ERROR", "query must contain searchable characters", field="query")

        def _score(issue):
            hay = " ".join(
                [
                    str(issue.get("title") or ""),
                    str(issue.get("description") or ""),
                    str(issue.get("identifier") or ""),
                ]
            ).lower()
            # simple relevance: token occurrences + phrase bonus
            score = 0
            for tok in q_tokens:
                score += hay.count(tok)
            phrase = query.strip().lower()
            if phrase and phrase in hay:
                score += 5
            # identifier prefix boost
            if (issue.get("identifier") or "").lower().startswith(query.strip().lower()):
                score += 3
            return score

        scored = []
        for i in rows:
            sc = _score(i)
            if sc > 0:
                scored.append((sc, i))

        scored.sort(key=lambda x: (x[0], _dt(x[1].get("updated_at")), _dt(x[1].get("created_at")), str(x[1].get("id", ""))), reverse=True)

        total = len(scored)
        page_pairs = scored[off:off + limit]
        page = [p[1] for p in page_pairs]
        next_off = off + len(page)
        has_more = next_off < total
        next_cursor = _make_cursor(next_off) if has_more else None

        _log(
            endpoint,
            "OK",
            meta={
                "returned": len(page),
                "total": total,
                "offset": off,
                "workspace_id": workspace_id,
                "team_id": team_id,
                "latency_ms": int((time.time() - start) * 1000),
            },
        )
        return {
            "data": {
                "issues": page,
                "page_info": {"limit": limit, "total": total, "has_more": has_more, "next_cursor": next_cursor},
            }
        }
    except Exception as e:
        _log(endpoint, "ERROR", "Internal error", {"detail": str(e)})
        return _err("CONFLICT", "Internal error")

def get_issue(issue_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0308000" if __import__("os").path.isdir("./environment_mix/0308000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    endpoint = "get_issue"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log(status_code, workspace_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - started) * 1000)
        row = {
            "id": f"lin_req_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}",
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": latency_ms,
            "credential_id": None,
            "workspace_id": workspace_id,
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    # Do not over-reject: accept any non-empty string (callers may pass the wrong id type; should return NOT_FOUND, not VALIDATION_ERROR)
    if not isinstance(issue_id, str) or not issue_id:
        _log("VALIDATION_ERROR", meta={"field": "issue_id"})
        return _err("VALIDATION_ERROR", "issue_id must be a non-empty string", field="issue_id")

    issues_data = _load("issues.json")
    issue_rows = _rows(issues_data)

    issue = None
    for r in issue_rows:
        if isinstance(r, dict) and r.get("id") == issue_id:
            issue = r
            break

    if issue is None:
        _log("NOT_FOUND", meta={"issue_id": issue_id})
        return _err("NOT_FOUND", "Issue not found", issue_id=issue_id)

    # Business rule: return 404 if logically deleted
    if issue.get("status") == "deleted":
        _log("NOT_FOUND", workspace_id=issue.get("workspace_id"), meta={"issue_id": issue_id})
        return _err("NOT_FOUND", "Issue not found", issue_id=issue_id)

    _log("OK", workspace_id=issue.get("workspace_id"), meta={"issue_id": issue_id})
    return {"issue": issue}

def delete_issue(id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0308000" if __import__("os").path.isdir("./environment_mix/0308000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    endpoint = "delete_issue"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log(status_code, workspace_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - started) * 1000)
        row = {
            "id": f"lin_req_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}",
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": latency_ms,
            "credential_id": None,
            "workspace_id": workspace_id,
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    # Accept any non-empty string; wrong id types should yield NOT_FOUND.
    if not isinstance(id, str) or not id:
        _log("VALIDATION_ERROR", meta={"field": "id"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    issues_data = _load("issues.json")
    issue_rows = _rows(issues_data)

    issue_idx = None
    issue = None
    for i, r in enumerate(issue_rows):
        if isinstance(r, dict) and r.get("id") == id:
            issue = r
            issue_idx = i
            break

    if issue is None:
        _log("NOT_FOUND", meta={"id": id})
        return _err("NOT_FOUND", "Issue not found", id=id)

    if issue.get("status") == "deleted":
        _log("NOT_FOUND", workspace_id=issue.get("workspace_id"), meta={"id": id})
        return _err("NOT_FOUND", "Issue not found", id=id)

    if issue.get("status") != "active":
        _log("INVALID_TRANSITION", workspace_id=issue.get("workspace_id"), meta={"id": id})
        return _err("INVALID_TRANSITION", f"Cannot delete issue from status {issue.get('status')}", id=id)

    updated = dict(issue)
    updated["status"] = "deleted"
    updated["updated_at"] = _now_iso()
    issue_rows[issue_idx] = updated

    if isinstance(issues_data, dict) and isinstance(issues_data.get("rows"), list):
        issues_data["rows"] = issue_rows
        _save("issues.json", issues_data)
    else:
        _save("issues.json", issue_rows)

    _log("OK", workspace_id=updated.get("workspace_id"), meta={"id": id})
    return {"issue": updated}
